+    if (maxDepth < 0)
+        ErrorExit(loc, "\"maxdepth\" must be non-negative for the photon-map integrator.");
+    if (maxPhotonDepth < 0)
+        ErrorExit(loc, "\"maxphotondepth\" must be non-negative for the photon-map "
