   321	std::unique_ptr<PhotonMapIntegrator> PhotonMapIntegrator::Create(
   322	    const ParameterDictionary &parameters, const RGBColorSpace *colorSpace, Camera camera,
   323	    Sampler sampler, Primitive aggregate, std::vector<Light> lights, const FileLoc *loc) {
   324	    int maxDepth = parameters.GetOneInt("maxdepth", 5);
   325	    int maxPhotonDepth = parameters.GetOneInt("maxphotondepth", 10);
   326	
   327	    int globalPhotonCount = parameters.GetOneInt(
   328	        "photons", parameters.GetOneInt("globalphotons", 100000));
   329	    int causticPhotonCount = parameters.GetOneInt("causticphotons", 10000);
   330	
   331	    Float globalRadius =
   332	        parameters.GetOneFloat("radius", parameters.GetOneFloat("maxdist", 0.1f));
   333	    Float causticRadius = parameters.GetOneFloat(
   334	        "causticradius", parameters.GetOneFloat("causticmaxdist", globalRadius));
   335	    int maxPhotons = parameters.GetOneInt("maxphotons", 50);
   336	    bool caustics = parameters.GetOneBool("caustics", true);
   337	    int seed = parameters.GetOneInt("seed", Options->seed);
   338	
   339	    if (maxDepth < 0)
   340	        ErrorExit(loc, "\"maxdepth\" must be non-negative for the photon-map integrator.");
   341	    if (maxPhotonDepth < 0)
   342	        ErrorExit(loc, "\"maxphotondepth\" must be non-negative for the photon-map "
   343	                       "integrator.");
   344	    if (globalPhotonCount < 0 || causticPhotonCount < 0)
   345	        ErrorExit(loc, "Photon counts must be non-negative.");
   346	    if (globalRadius <= 0 || causticRadius <= 0)
   347	        ErrorExit(loc, "Photon-map search radii must be positive.");
   348	    if (maxPhotons < 0)
   349	        ErrorExit(loc, "\"maxphotons\" must be non-negative.");
   350	
   351	    if (!camera.GetFilm().Is<RGBFilm>() && !camera.GetFilm().Is<GBufferFilm>())
   352	        ErrorExit(loc, "The photon-map integrator requires an RGB or gbuffer film.");
   353	
   354	    return std::make_unique<PhotonMapIntegrator>(
   355	        camera, sampler, aggregate, lights, maxDepth, maxPhotonDepth,
   356	        globalPhotonCount, causticPhotonCount, globalRadius, causticRadius, maxPhotons,
   357	        caustics, seed, colorSpace);
   358	}
