   369	SampledSpectrum PhotonMapIntegrator::SampleLd(const SurfaceInteraction &intr,
   370	                                              const BSDF &b, SampledWavelengths &lambda,
   371	                                              Sampler sampler,
   372	                                              LightSampler lightSampler) const {
   373	    const BSDF *bsdf = &b;
   374	    LightSampleContext ctx(intr);
   375	    BxDFFlags flags = bsdf->Flags();
   376	    if (IsReflective(flags) && !IsTransmissive(flags))
   377	        ctx.pi = intr.OffsetRayOrigin(intr.wo);
   378	    else if (IsTransmissive(flags) && !IsReflective(flags))
   379	        ctx.pi = intr.OffsetRayOrigin(-intr.wo);
   380	
   381	    pstd::optional<SampledLight> sampledLight =
   382	        lightSampler.Sample(ctx, sampler.Get1D());
   383	    if (!sampledLight)
   384	        return {};
   385	
   386	    Light light = sampledLight->light;
   387	    DCHECK(light && sampledLight->p > 0);
   388	    pstd::optional<LightLiSample> ls =
   389	        light.SampleLi(ctx, sampler.Get2D(), lambda, true);
   390	    if (!ls || !ls->L || ls->pdf == 0)
   391	        return {};
   392	
   393	    Vector3f wo = intr.wo, wi = ls->wi;
   394	    SampledSpectrum f = bsdf->f(wo, wi) * AbsDot(wi, intr.shading.n);
   395	    if (!f || !Unoccluded(intr, ls->pLight))
   396	        return {};
   397	
   398	    Float p_l = sampledLight->p * ls->pdf;
   399	    if (IsDeltaLight(light.Type()))
   400	        return ls->L * f / p_l;
   401	
   402	    Float p_b = bsdf->PDF(wo, wi);
   403	    Float w_l = PowerHeuristic(1, p_l, 1, p_b);
   404	    return w_l * ls->L * f / p_l;
   405	}
